code.source:
#include <array>
#include <iostream>
using namespace std;

int main() {
    array<int, 3> a = {5, 6, 7};
    cout << a.size() << endl;
    cout << a.at(1) << endl;
    a.fill(0);
    cout << a[2] << endl;
    return 0;
}

#include <array>
#include <iostream>
using namespace std;

int main() {
    array<int, 3> a = {1, 2, 3};
    array<int, 3> b = a;
    b[0] = 9;
    cout << boolalpha << (a == b) << endl;
    cout << a[0] << " " << b[0] << endl;
    return 0;
}

